-- Check traders with no compliance cases (through transaction records)
SELECT COUNT(*) FROM trader t WHERE NOT EXISTS (
    SELECT 1 FROM transactionrecord tr 
    JOIN compliancecase cc ON cc.transref = tr.transreg 
    WHERE tr.trdref = t.tradereg
);

-- Check which traders have no compliance cases
SELECT t.tradereg, t.tradekind FROM trader t WHERE NOT EXISTS (
    SELECT 1 FROM transactionrecord tr 
    JOIN compliancecase cc ON cc.transref = tr.transreg 
    WHERE tr.trdref = t.tradereg
);
